# Databricks notebook source
# COMMAND ----------

import json, requests
from databricks.sdk import WorkspaceClient
from databricks.sdk.config import Config

w = WorkspaceClient()

# Get auth headers properly
config = w.config
auth_headers = {}
# Use the SDK's built-in HTTP client to handle auth
import urllib.request

host = config.host.rstrip('/')
results = {}

# Prepare headers using SDK
req_ctx = config._new_request_config(host)
headers_obj = {}
try:
    # Try to get the auth headers from the SDK
    creds = config.credentials_provider()
    visitor = creds(config)
    fake_req = type('R', (), {'headers': {}})()
    visitor(fake_req)
    auth_headers = fake_req.headers
    results['auth_header_keys'] = list(auth_headers.keys())
except Exception as e:
    results['auth_error'] = str(e)
    # Fallback: try using the notebook context token
    import subprocess
    try:
        # Try using dbutils to get token
        token = dbutils.notebook.entry_point.getDbutils().notebook().getContext().apiToken().get()
        auth_headers = {"Authorization": f"Bearer {token}"}
        results['auth_method'] = 'dbutils_token'
    except Exception as e2:
        results['auth_fallback_error'] = str(e2)

# Try synced tables API
paths_to_try = [
    "/api/2.0/unity-catalog/synced-tables",
    "/api/2.0/feature-engineering/synced-tables",
    "/api/2.0/online-tables",
]

payload = {
    "name": "workspace.mlpab62f111.accountse81ff1_online",
    "spec": {
        "source_table_full_name": "workspace.mlpab62f111.accountse81ff1",
        "primary_key_columns": ["row_id"],
        "timeseries_key": "updated_at",
        "run_triggered": {}
    }
}

headers = {**auth_headers, "Content-Type": "application/json"}
for path in paths_to_try:
    url = f"{host}{path}"
    r = requests.post(url, headers=headers, json=payload, timeout=10)
    results[path] = {"status_code": r.status_code, "response": r.text[:500]}

dbutils.notebook.exit(json.dumps(results))

